class Solution:
    def numberToWords(self, num: int) -> str:
        if num == 0:
            return "Zero"
        out = []
        if num < 0:
            out.append("Negative")
            num = -num

        def below1000(n: int):
            if n >= 100:
                out.append(ones[n // 100])
                out.append("Hundred")
                n %= 100
            if n >= 20:
                out.append(tens[n // 10])
                n %= 10
            if n > 0:
                out.append(ones[n])

        chunks = []
        tmp = num
        while tmp > 0:
            chunks.append(tmp % 1000)
            tmp //= 1000
        for i in range(len(chunks) - 1, -1, -1):
